#include <bits/stdc++.h>
using namespace std;
vector<vector<int>> floodFill(vector<vector<int>> image, int row, int column, int color) { if (image.empty() || image[0].empty() || row<0 || row>=static_cast<int>(image.size()) || column<0 || column>=static_cast<int>(image[0].size())) throw out_of_range("invalid start"); int original=image[row][column]; if (original==color) return image; queue<pair<int,int>> pending; pending.push({row,column}); image[row][column]=color; const int dr[4]={-1,1,0,0}, dc[4]={0,0,-1,1}; while (!pending.empty()) { auto [r,c]=pending.front(); pending.pop(); for (int i=0;i<4;++i) { int nr=r+dr[i], nc=c+dc[i]; if (nr>=0 && nr<static_cast<int>(image.size()) && nc>=0 && nc<static_cast<int>(image[0].size()) && image[nr][nc]==original) { image[nr][nc]=color; pending.push({nr,nc}); } } } return image; }
